a3.text:
PREFIX ex: <http://example.org/>
SELECT ?person ?org WHERE {
  ?person a ex:Person ; ex:worksFor ?org .
  ?org a ex:Org ; ex:locatedIn ex:lyon .
}
LIMIT 1000

lists.text:
PREFIX ex: <http://example.org/>
SELECT * {
  ?s ex:p ?a, ?b , ?c ;
     ex:q ?d ;
     ex:r ?e .
}

locked-after.text:
PREFIX ex: <http://example.org/>
SELECT * WHERE {
  ?a ex:p ?b .
  BIND(?b + 1 AS ?c)
  MINUS { ?a ex:q ?d }
}

optional.text:
PREFIX ex: <http://example.org/>
SELECT * WHERE {
  ?org ex:name ?n .
  OPTIONAL { ?org ex:locatedIn ?c . } .
  OPTIONAL { ?org ex:size ?z . ?z ex:unit ?u }
}

optional-iri.text:
PREFIX ex: <http://example.org/>
SELECT * {
  ?s ex:p ?o .
  OPTIONAL { ex:a ex:q ?x }
}

two-moved.text:
PREFIX ex: <http://example.org/>
SELECT * {
  ?s ex:z ?z .
  ?s ex:p ?a .
  ?s ex:q ?b .
}
